/**
 * Rule-based weekly briefing JSON. The notify team (packages/notify) renders/sends it.
 * AI-LATER: `headline` and `suggestions` wording can be generated by the agent gateway.
 */
import type { Application, CalendarEvent, Goal, Milestone, Opportunity, Student, Task } from '../domain';
import { addDays, dubaiInstant } from '../lib/time';
import { planWeek, type WeekPlan } from './planner';
import { scoreOpportunity } from './matching';

export interface WeeklyBriefing {
  student_id: string;
  week_start: string;
  week_end: string;
  generated_at: string;
  headline: string;
  tasks: {
    due_this_week: { id: string; title: string; due_at: string | null; kind: Task['kind'] }[];
    overdue: { id: string; title: string; due_at: string | null }[];
    open_count: number;
  };
  calendar: { event_count: number; busiest_day: string | null };
  plan: WeekPlan['stats'] & { unscheduled_titles: string[] };
  goals: { id: string; title: string; progress: number; next_milestone: { title: string; due_date: string | null } | null }[];
  applications: { id: string; opportunity_title: string; status: Application['status']; open_items: number; deadline: string | null }[];
  opportunities: { id: string; title: string; type: Opportunity['type']; deadline: string | null; score: number; reasons: string[] }[];
  suggestions: string[];
}

export function buildWeeklyBriefing(input: {
  student: Student;
  tasks: Task[];
  events: CalendarEvent[];
  goals: Goal[];
  milestones: Milestone[];
  applications: Application[];
  opportunities: Opportunity[];
  weekStart: string;
  now: Date;
}): WeeklyBriefing {
  const { student, now, weekStart } = input;
  const weekEnd = addDays(weekStart, 6);
  const startMs = dubaiInstant(weekStart).getTime();
  const endMs = dubaiInstant(addDays(weekStart, 7)).getTime();
  const open = input.tasks.filter((t) => t.status === 'todo' || t.status === 'doing');
  const dueThisWeek = open
    .filter((t) => t.due_at && Date.parse(t.due_at) >= Math.max(startMs, now.getTime()) && Date.parse(t.due_at) < endMs)
    .sort((a, b) => Date.parse(a.due_at!) - Date.parse(b.due_at!));
  const overdue = open.filter((t) => t.due_at && Date.parse(t.due_at) < now.getTime());

  const weekEvents = input.events.filter((e) => Date.parse(e.start_at) < endMs && Date.parse(e.end_at) > startMs);
  const perDay = new Map<string, number>();
  for (const e of weekEvents) {
    const d = new Date(Date.parse(e.start_at) + 4 * 3600_000).toISOString().slice(0, 10);
    perDay.set(d, (perDay.get(d) ?? 0) + 1);
  }
  const busiest = [...perDay.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;

  const plan = planWeek(input.tasks, input.events, { weekStart, now });

  const goals = input.goals.filter((g) => g.status === 'active').map((g) => {
    const next = input.milestones.filter((m) => m.goal_id === g.id && !m.done)
      .sort((a, b) => (a.due_date ?? '9999').localeCompare(b.due_date ?? '9999'))[0];
    return { id: g.id, title: g.title, progress: g.progress, next_milestone: next ? { title: next.title, due_date: next.due_date } : null };
  });

  const oppById = new Map(input.opportunities.map((o) => [o.id, o]));
  const applications = input.applications
    .filter((a) => a.status === 'saved' || a.status === 'preparing')
    .map((a) => {
      const o = oppById.get(a.opportunity_id);
      return { id: a.id, opportunity_title: o?.title ?? 'Unknown opportunity', status: a.status,
        open_items: a.checklist.filter((c) => !c.done).length, deadline: o?.deadline ?? null };
    })
    .sort((a, b) => (a.deadline ?? '9999').localeCompare(b.deadline ?? '9999'));

  const appliedIds = new Set(input.applications.map((a) => a.opportunity_id));
  const goalCategories = input.goals.filter((g) => g.status === 'active').map((g) => g.category);
  const opportunities = input.opportunities
    .filter((o) => !appliedIds.has(o.id))
    .map((o) => ({ o, m: scoreOpportunity(student, o, { now, goalCategories }) }))
    .filter((x) => x.m.eligible && x.m.score >= 40)
    .sort((a, b) => b.m.score - a.m.score)
    .slice(0, 3)
    .map(({ o, m }) => ({ id: o.id, title: o.title, type: o.type, deadline: o.deadline, score: m.score, reasons: m.reasons }));

  const suggestions: string[] = [];
  if (overdue.length) suggestions.push(`Clear ${overdue.length} overdue task${overdue.length > 1 ? 's' : ''} first: ${overdue.map((t) => t.title).join(', ')}.`);
  if (plan.unscheduled.length || plan.partially_scheduled.length) suggestions.push(`Your week is tight — ${plan.stats.unscheduled_minutes} min of work did not fit. Consider moving an activity or asking for an extension.`);
  const urgentApp = applications.find((a) => a.deadline && Date.parse(a.deadline) - now.getTime() < 14 * 86400_000);
  if (urgentApp) suggestions.push(`"${urgentApp.opportunity_title}" closes soon and has ${urgentApp.open_items} checklist item(s) left.`);
  const stalled = goals.find((g) => g.progress < 25 && g.next_milestone);
  if (stalled) suggestions.push(`Make progress on "${stalled.title}": next step is "${stalled.next_milestone!.title}".`);
  if (opportunities[0]) suggestions.push(`Look at "${opportunities[0].title}" (${opportunities[0].score}% match).`);
  if (!suggestions.length) suggestions.push('You are on track this week. Keep it up!');

  const name = student.preferred_name ?? student.full_name.split(' ')[0];
  const headline = `${name}, you have ${dueThisWeek.length} task${dueThisWeek.length === 1 ? '' : 's'} due this week` +
    (overdue.length ? ` and ${overdue.length} overdue` : '') +
    `; ${Math.round(plan.stats.planned_minutes / 6) / 10} h of study planned.`;

  return {
    student_id: student.id, week_start: weekStart, week_end: weekEnd, generated_at: now.toISOString(), headline,
    tasks: {
      due_this_week: dueThisWeek.map((t) => ({ id: t.id, title: t.title, due_at: t.due_at, kind: t.kind })),
      overdue: overdue.map((t) => ({ id: t.id, title: t.title, due_at: t.due_at })),
      open_count: open.length,
    },
    calendar: { event_count: weekEvents.length, busiest_day: busiest },
    plan: { ...plan.stats, unscheduled_titles: [...plan.unscheduled, ...plan.partially_scheduled].map((u) => u.title) },
    goals, applications, opportunities, suggestions,
  };
}
